internal sealed class DarkMenu : ContextMenuStrip {
    static readonly Color MenuSurface=Color.FromArgb(33,33,37),MenuHover=Color.FromArgb(61,62,69),MenuBorder=Color.FromArgb(87,88,96);
    readonly System.Collections.Generic.HashSet<ToolStripDropDown> styled=new System.Collections.Generic.HashSet<ToolStripDropDown>();
    internal DarkMenu(){Renderer=new MenuPainter();BackColor=MenuSurface;ForeColor=Color.FromArgb(242,243,246);Font=Theme.Font(10);ShowImageMargin=false;ShowCheckMargin=false;Padding=new Padding(7);DropShadowEnabled=true;Opening+=delegate{Style(Items);};SizeChanged+=delegate{RoundPopup(this);};Opened+=delegate{RoundPopup(this);};}
    static void RoundPopup(ToolStripDropDown popup){if(popup.Width<3||popup.Height<3)return;var old=popup.Region;using(var shape=Theme.Round(new Rectangle(0,0,popup.Width,popup.Height),12))popup.Region=new Region(shape);if(old!=null)old.Dispose();}
    void Style(ToolStripItemCollection items){foreach(ToolStripItem item in items){item.Padding=new Padding(29,8,14,8);item.ForeColor=ForeColor;item.Font=Font;var menu=item as ToolStripMenuItem;if(menu!=null){var popup=menu.DropDown;popup.BackColor=MenuSurface;popup.ForeColor=ForeColor;popup.Renderer=Renderer;popup.Padding=new Padding(7);popup.DropShadowEnabled=true;var dropdown=popup as ToolStripDropDownMenu;if(dropdown!=null){dropdown.ShowImageMargin=false;dropdown.ShowCheckMargin=false;}if(styled.Add(popup)){popup.SizeChanged+=delegate{RoundPopup(popup);};popup.Opened+=delegate{RoundPopup(popup);};}Style(popup.Items);}}}
    sealed class MenuPainter : ToolStripProfessionalRenderer {
        internal MenuPainter():base(new Colors()){RoundedEdges=false;}
        static string Icon(ToolStripItem item){var menu=item as ToolStripMenuItem;if(menu!=null&&menu.Checked)return "\uE73E";string text=item.Text.ToLowerInvariant();if(text.Contains("playlist"))return text.Contains("new")?"\uE710":"\uE8F1";if(text.Contains("artist"))return "\uE77B";if(text.Contains("album"))return "\uE93C";if(text.Contains("less")||text.Contains("hide"))return "\uE711";if(text.Contains("offline")||text.Contains("download"))return "\uE896";if(text.Contains("next"))return "\uE893";if(text.Contains("previous"))return "\uE892";if(text.Contains("queue"))return "\uE8FD";if(text.Contains("radio"))return "\uE93E";if(text.Contains("like"))return "\uEB52";if(text.Contains("play")||text.Contains("pause"))return "\uE768";if(text.Contains("exit")||text.Contains("delete")||text.Contains("remove"))return "\uE74D";return "";}
        protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e){e.Graphics.Clear(MenuSurface);}
        protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e){
            var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;
            if((e.Item.Selected||e.Item.Pressed)&&e.Item.Enabled){using(var p=Theme.Round(new Rectangle(2,1,e.Item.Width-4,e.Item.Height-2),8))using(var b=new SolidBrush(MenuHover))g.FillPath(b,p);}
            string icon=Icon(e.Item);if(icon.Length>0)using(var font=new Font("Segoe MDL2 Assets",12))TextRenderer.DrawText(g,icon,font,new Rectangle(10,0,23,e.Item.Height),e.Item.Enabled?Color.FromArgb(221,225,233):Color.FromArgb(143,144,153),TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter|TextFormatFlags.NoPadding);
        }
        protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e){var r=e.TextRectangle;r.X=Math.Max(38,r.X);r.Width=Math.Max(1,e.Item.Width-r.X-26);TextRenderer.DrawText(e.Graphics,e.Text,e.TextFont,r,e.Item.Enabled?Color.FromArgb(242,243,246):Color.FromArgb(154,155,164),TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.NoPadding);}
        protected override void OnRenderArrow(ToolStripArrowRenderEventArgs e){var r=e.ArrowRectangle;int x=r.Left+r.Width/2,y=r.Top+r.Height/2;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(e.Item.Enabled?Color.FromArgb(228,231,239):Color.FromArgb(150,151,160),1.7f)){if(e.Direction==ArrowDirection.Left)e.Graphics.DrawLines(pen,new[]{new Point(x+2,y-4),new Point(x-2,y),new Point(x+2,y+4)});else e.Graphics.DrawLines(pen,new[]{new Point(x-2,y-4),new Point(x+2,y),new Point(x-2,y+4)});}}
        protected override void OnRenderItemCheck(ToolStripItemImageRenderEventArgs e){}
        protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=Theme.Round(new Rectangle(0,0,e.ToolStrip.Width-1,e.ToolStrip.Height-1),12))using(var p=new Pen(MenuBorder))e.Graphics.DrawPath(p,shape);}
        sealed class Colors:ProfessionalColorTable{public override Color ToolStripDropDownBackground{get{return MenuSurface;}}public override Color ImageMarginGradientBegin{get{return MenuSurface;}}public override Color ImageMarginGradientMiddle{get{return MenuSurface;}}public override Color ImageMarginGradientEnd{get{return MenuSurface;}}public override Color SeparatorDark{get{return MenuBorder;}}public override Color SeparatorLight{get{return MenuSurface;}}public override Color CheckBackground{get{return MenuHover;}}public override Color CheckSelectedBackground{get{return MenuHover;}}}
    }
}
internal sealed class ChoiceButton : Button {
    internal readonly System.Collections.Generic.List<object> Items=new System.Collections.Generic.List<object>();int selected=-1;
    internal event EventHandler SelectedIndexChanged;
    internal int SelectedIndex{get{return selected;}set{if(selected==value)return;selected=value;Invalidate();if(SelectedIndexChanged!=null)SelectedIndexChanged(this,EventArgs.Empty);}}
    internal object SelectedItem{get{return selected>=0&&selected<Items.Count?Items[selected]:null;}}
    internal ChoiceButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    protected override void OnClick(EventArgs e){base.OnClick(e);var menu=new DarkMenu();for(int i=0;i<Items.Count;i++){int n=i;var item=new ToolStripMenuItem(Items[i].ToString()){Checked=i==selected};item.Click+=delegate{SelectedIndex=n;};menu.Items.Add(item);}menu.Closed+=delegate{BeginInvoke((Action)menu.Dispose);};menu.Show(this,new Point(0,Height+3));}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent.BackColor);Surface.Background(this,g);g.SmoothingMode=SmoothingMode.AntiAlias;using(var p=Theme.Round(new Rectangle(0,0,Width-1,Height-1),10))using(var b=new SolidBrush(Theme.Edge))g.FillPath(b,p);TextRenderer.DrawText(g,SelectedItem==null?"Choose":SelectedItem.ToString(),Font,new Rectangle(12,0,Width-36,Height),Theme.Paper,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);TextRenderer.DrawText(g,"⌄",Font,new Rectangle(Width-27,0,20,Height),Theme.Muted,TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter);if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(4,4,Width-8,Height-8));}
}
internal sealed class ToggleButton : Button {
    readonly Motion slide;readonly Func<bool> read;readonly Action<bool> write;
    internal ToggleButton(string name,Func<bool> get,Action<bool> set){AccessibleName=name;AccessibleRole=AccessibleRole.CheckButton;read=get;write=set;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;slide=new Motion(Invalidate);slide.To(get()?1:0,1);SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    protected override void OnClick(EventArgs e){base.OnClick(e);write(!read());slide.To(read()?1:0,145);}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent.BackColor);Surface.Background(this,g);g.SmoothingMode=SmoothingMode.AntiAlias;var r=new Rectangle((Width-48)/2,(Height-26)/2,48,26);using(var p=Theme.Round(r,13))using(var b=new SolidBrush(Motion.Mix(Theme.Edge,Theme.Paper,slide.Value)))g.FillPath(b,p);using(var b=new SolidBrush(Motion.Mix(Theme.Paper,Theme.Ink,slide.Value)))g.FillEllipse(b,r.X+4+20*slide.Value,r.Y+4,18,18);if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,ClientRectangle);}
    protected override void Dispose(bool disposing){if(disposing)slide.Dispose();base.Dispose(disposing);}
}
internal static class DialogUI {
    [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr h,int attribute,ref int value,int size);
    internal static void Apply(Form form){form.BackColor=Theme.Ink;form.ForeColor=Theme.Paper;form.Font=Theme.Font(10);form.AutoScaleMode=AutoScaleMode.Dpi;form.StartPosition=FormStartPosition.CenterParent;form.ShowInTaskbar=false;form.MaximizeBox=form.MinimizeBox=false;form.FormBorderStyle=FormBorderStyle.FixedDialog;form.HandleCreated+=delegate{try{int on=1;DwmSetWindowAttribute(form.Handle,20,ref on,4);}catch(DllNotFoundException){}catch(EntryPointNotFoundException){}};}
    internal static Label Label(Control parent,string text,int x,int y,int w,int h,float size,bool bold=false){var l=new Label{Text=text,Bounds=new Rectangle(x,y,w,h),Font=Theme.Font(size,bold),ForeColor=bold?Theme.Paper:Theme.Muted,AutoEllipsis=true};parent.Controls.Add(l);return l;}
    internal static Form Create(string title,string subtitle,int width,int height){var f=new Form{Text=title,ClientSize=new Size(width,height)};Apply(f);Label(f,title,24,22,width-48,39,21,true);Label(f,subtitle,25,66,width-50,46,10);return f;}
    internal static TextBox Field(Control parent,string label,string value,int x,int y,int width,bool password=false){Label(parent,label,x,y,width,24,10,true);var host=new Surface{Bounds=new Rectangle(x,y+28,width,43),BackColor=Theme.Ink};parent.Controls.Add(host);host.PaintSurface=delegate(Graphics g,Rectangle r){g.SmoothingMode=SmoothingMode.AntiAlias;using(var p=Theme.Round(new Rectangle(0,0,r.Width-1,r.Height-1),10))using(var b=new SolidBrush(Theme.Card))using(var pen=new Pen(host.ContainsFocus?Theme.Peach:Theme.Edge)){g.FillPath(b,p);g.DrawPath(pen,p);}};var box=new TextBox{Text=value??"",BorderStyle=BorderStyle.None,BackColor=Theme.Card,ForeColor=Theme.Paper,Font=Theme.Font(11),UseSystemPasswordChar=password,Bounds=new Rectangle(13,11,width-26,24)};host.Controls.Add(box);if(password)new SecretVeil(box);box.GotFocus+=delegate{host.Invalidate();};box.LostFocus+=delegate{host.Invalidate();};return box;}
    internal static DialogResult Show(IWin32Window owner,string text,string title="Noctune",MessageBoxButtons buttons=MessageBoxButtons.OK,MessageBoxIcon icon=MessageBoxIcon.None){using(var d=Create(title,"",460,280)){Label(d,text,24,76,412,142,10);var ok=new SoftButton(buttons==MessageBoxButtons.YesNo?"Confirm":"OK",delegate{d.DialogResult=buttons==MessageBoxButtons.YesNo?DialogResult.Yes:DialogResult.OK;},true);ok.SetBounds(326,222,110,36);d.Controls.Add(ok);d.AcceptButton=ok;if(buttons==MessageBoxButtons.YesNo){var cancel=new SoftButton("Cancel",delegate{d.DialogResult=DialogResult.No;});cancel.SetBounds(206,222,110,36);d.Controls.Add(cancel);d.CancelButton=cancel;}return d.ShowDialog(owner);}}
    internal static DialogResult Show(string text,string title,MessageBoxButtons buttons,MessageBoxIcon icon){return Show(null,text,title,buttons,icon);}
}
